rtems_task Init(rtems_task_argument argument)
{
    initialize_system_spec();
    Hal_Init();
    Monitor_Init();
    FaultHandler_Init();
    initialize_devices();
    initialize_transport();
    initialize_transport_bus_maps();
#ifdef USE_ROUTING_TABLE
    initialize_routing();
#endif

    enum SystemBus valid_buses[SYSTEM_BUSES_NUMBER] = { BUS_INVALID_ID };
    unsigned buses_index = 0;
    valid_buses[buses_index++] = BUS_BUS_1;
    Broker_initialize(valid_buses);
    initialize_interface_to_queue_map();

    rtems_semaphore_create(rtems_build_name('l', 'o', 'c', 'k'),
                           1, // Initial value, unlocked
                           RTEMS_BINARY_SEMAPHORE,
                           0, // Priority ceiling
                           &broker_Semaphore);


    rtems_semaphore_create(generate_new_partition_semaphore_name(),
                           1, // Initial value, unlocked
                           RTEMS_BINARY_SEMAPHORE,
                           0, // Priority ceiling
                           &teststart00_Semaphore);

    init_teststart00();
    rtems_semaphore_create(generate_new_partition_semaphore_name(),
                           1, // Initial value, unlocked
                           RTEMS_BINARY_SEMAPHORE,
                           0, // Priority ceiling
                           &testentrypoint_Semaphore);

    init_testentrypoint();

    Create_Thread_testentrypoint_pi_sp_if();
    Create_Thread_teststart00_pi_1_cyclic();
    Create_Thread_teststart00_samrh71rx();

    Start_Thread_testentrypoint_pi_sp_if();
    Start_Thread_teststart00_pi_1_cyclic();
    Start_Thread_teststart00_samrh71rx();

    (void) rtems_task_delete( RTEMS_SELF );
}

